/* @scripttype preserveParamNames */
export function applyAnchors(pattern: string) {
  const m1 = matches<`${StartAnchorMarker}${Hole<"startStripped">}`>(pattern)
  if (m1) {
    const m2 = matches<`${Hole<"bothStripped">}${EndAnchorMarker}`>(m1.startStripped)
    if (m2) {
      return m2.bothStripped
    }
    return appendNonRedundant(m1.startStripped, string)
  }
  const m3 = matches<`${Hole<"endStripped">}${EndAnchorMarker}`>(pattern)
  if (m3) {
    return prependNonRedundant(m3.endStripped, string)
  }
  return prependNonRedundant(appendNonRedundant(pattern, string), string)
}
