// ✓ appendNonRedundant: verified type-identical to the original
/* @scripttype preserveParamNames */
export function appendNonRedundant(base: string, suffix: string) {
  if (matches<typeof base>(string)) {
    if (matches<typeof suffix>(string)) {
      return string
    }
    return `${base}${suffix}`
  }
  if (matches<typeof base>(`${number}`)) {
    if (matches<typeof suffix>(`${number}`)) {
      return `${number}`
    }
    return `${base}${suffix}`
  }
  return `${base}${suffix}`
}
